    # Try to read common fields safely.
    # Resource collection: look for nearby resources "_resource" or "resources"
    # Pursuit-evasion: look for "evader" or "pursuer" hints
    # Territory control: look for "flag", "own_goal", "enemy_goal" or "territory_score"
    grid = observation.get("grid", [])
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    # Current position
    pos = observation.get("position", None)
    if isinstance(pos, (list, tuple)) and len(pos) >= 2:
        x, y = pos[0], pos[1]
    else:
        x = y = 0

    # Helpers to check around (inline, boundary-safe)
    def in_bounds(nx, ny):
        return 0 <= nx < width and 0 <= ny < height

    # Scan immediate neighborhood for cues
    for dx_i in (-1, 0, 1):
        for dy_i in (-1, 0, 1):
            if dx_i == 0 and dy_i == 0:
                continue
            nx, ny = x + dx_i, y + dy_i
            if not in_bounds(nx, ny):
                continue
            cell = None
            if isinstance(grid, list) and len(grid) > ny and len(grid[ny]) > nx:
                cell = grid[ny][nx]
            if cell is None:
                continue

            # Resource hint
            if isinstance(cell, str) and ("resource" in cell or "food" in cell or "gold" in cell or "loot" in cell):
                dx, dy = dx_i, dy_i
                return [dx, dy]

            # Evader hint (pursuit-evasion)
            if isinstance(cell, dict) and ("type" in cell):
                t = cell.get("type")
                if t == "evader" or t == "enemy" or t == "threat":
                    dx, dy = dx_i, dy_i
                    return [dx, dy]

            # Territory hint
            if isinstance(cell, dict) and ("claim" in cell or "enemy" in cell or "territory" in cell):
                dx, dy = dx_i, dy_i
                return [dx, dy]

    # If no cues, attempt to stay close to center or along safe axes
    # Try to move minimally towards center of grid if available
    if height and width:
        cx, cy = width // 2, height // 2
        if x < cx:
            dx = 1
        elif x > cx:
            dx = -1
        else:
            dx = 0

        if y < cy:
            dy = 1
        elif y > cy:
            dy = -1
        else:
            dy = 0

        # Clip to -1,0,1
        dx = max(-1, min(1, dx))
        dy = max(-1, min(1, dy))
        return [dx, dy]

    return [0, 0]

